-- 0366 PROD CHECK (after), read-only, ONE statement: npx --yes supabase@2.120.0 db query --linked -f scripts/ops/harness/more-ships/after.sql
-- Wanted: head 20260818000366; classes 157; new_classes 54; new_rows profiles 54, slots 220, cabins 54, recipes 54, materials 238, requirements 121;
-- old_rows and functions THE SAME TEXT as before.sql printed (no older class, recipe, requirement, line, merchant hull, loadout or function moved); name_clash 0;
-- named_by_npc_or_knob 0; news_row 1; ships_of_new_classes 0 at the deploy (it grows as players build: that is the feature).
-- Then the golden digest again (scripts/ops/harness/two-sides/golden.sql): the same `digest` as before. NO 30-minute fight after-check is needed: no rule, knob or NPC hull moved.
-- Every function read is STABLE or IMMUTABLE; no game function is called; nothing is written.
-- Generated by scripts/ops/harness/more-ships/gen-0366.mjs with the migration, from the same code list and the same digest texts.
begin transaction read only;
with n(codes) as (values (array['bergantim', 'schnigge', 'balinger', 'brigantin', 'galeotta', 'firkate', 'lancaran', 'shaochuan', 'bahansen', 'sahuseon', 'galeoncete', 'greatgalley', 'roberge', 'goke', 'wugong', 'gale', 'galera', 'galcapitana', 'kalyata', 'parau', 'ghali', 'mengchong', 'mekura', 'geomseon', 'daemaeng', 'naucap', 'kraweel', 'nef', 'barza', 'louchuan', 'tekkosen', 'friedeschiff', 'wafter', 'almiranta', 'jungmaeng', 'caravelao', 'chalupa', 'tartana', 'boum', 'sayka', 'bezaisen', 'nao', 'kogge', 'byeongjo', 'kenminsen', 'kotia', 'hoy', 'holk', 'cocca', 'caochuan', 'taforeia', 'hourque', 'jong', 'navegrossa']::text[])),
     nm(code, name) as (values ('bergantim', 'Bergantim'), ('schnigge', 'Schnigge'), ('balinger', 'Balinger'), ('brigantin', 'Brigantin'), ('galeotta', 'Galeotta'), ('firkate', 'Firkate'), ('lancaran', 'Lancaran'), ('shaochuan', 'Shaochuan'), ('bahansen', 'Bahansen'), ('sahuseon', 'Sahuseon'), ('galeoncete', 'Galeoncete'), ('greatgalley', 'Great Galley'), ('roberge', 'Roberge'), ('goke', 'Göke'), ('wugong', 'Wugongchuan'), ('gale', 'Galé'), ('galera', 'Galera'), ('galcapitana', 'Galea capitana'), ('kalyata', 'Kalyata'), ('parau', 'Parau'), ('ghali', 'Ghali'), ('mengchong', 'Mengchong'), ('mekura', 'Mekurabune'), ('geomseon', 'Geomseon'), ('daemaeng', 'Daemaengseon'), ('naucap', 'Nau capitânia'), ('kraweel', 'Kraweel'), ('nef', 'Nef'), ('barza', 'Barza'), ('louchuan', 'Louchuan'), ('tekkosen', 'Tekkōsen'), ('friedeschiff', 'Friedeschiff'), ('wafter', 'Wafter'), ('almiranta', 'Almiranta'), ('jungmaeng', 'Jungmaengseon'), ('caravelao', 'Caravelão'), ('chalupa', 'Chalupa'), ('tartana', 'Tartana'), ('boum', 'Boum'), ('sayka', 'Şayka'), ('bezaisen', 'Bezaisen'), ('nao', 'Nao'), ('kogge', 'Kogge'), ('byeongjo', 'Byeongjoseon'), ('kenminsen', 'Kenminsen'), ('kotia', 'Kotia'), ('hoy', 'Hoy'), ('holk', 'Holk'), ('cocca', 'Cocca'), ('caochuan', 'Caochuan'), ('taforeia', 'Taforeia'), ('hourque', 'Hourque'), ('jong', 'Jong'), ('navegrossa', 'Nave grossa'))
select jsonb_build_object(
  'head', (select max(version) from supabase_migrations.schema_migrations),
  'classes', (select count(*) from public.ship_classes),
  'new_classes', (select count(*) from public.ship_classes c, n where c.code = any (n.codes)),
  'new_rows', jsonb_build_object(
     'profiles', (select count(*) from public.class_profile x, n where x.class_code = any (n.codes)),
     'slots', (select count(*) from public.class_slots x, n where x.class_code = any (n.codes)),
     'cabins', (select count(*) from public.class_cabins x, n where x.class_code = any (n.codes)),
     'recipes', (select count(*) from public.hull_recipes x, n where x.class_code = any (n.codes)),
     'materials', (select count(*) from public.hull_recipe_goods x, n where x.class_code = any (n.codes)),
     'requirements', (select count(*) from public.skill_requirements x, n where x.subject_kind = 'hull' and x.subject_code = any (n.codes))),
  'old_rows', (
  select md5(concat_ws('#',
    (select string_agg(to_jsonb(c)::text, '|' order by c.code) from public.ship_classes c where c.code <> all ((select codes from n)::text[])),
    (select string_agg(to_jsonb(x)::text, '|' order by x.class_code) from public.class_profile x where x.class_code <> all ((select codes from n)::text[])),
    (select string_agg(to_jsonb(x)::text, '|' order by x.class_code, x.slot) from public.class_slots x where x.class_code <> all ((select codes from n)::text[])),
    (select string_agg(to_jsonb(x)::text, '|' order by x.class_code) from public.class_cabins x where x.class_code <> all ((select codes from n)::text[])),
    (select string_agg(to_jsonb(x)::text, '|' order by x.class_code, x.slot) from public.class_slot_unlocks x),
    (select string_agg(to_jsonb(x)::text, '|' order by x.class_code) from public.hull_recipes x where x.class_code <> all ((select codes from n)::text[])),
    (select string_agg(to_jsonb(x)::text, '|' order by x.class_code, x.good_id) from public.hull_recipe_goods x where x.class_code <> all ((select codes from n)::text[])),
    (select string_agg(to_jsonb(x)::text, '|' order by x.class_code, x.item_code) from public.hull_recipe_items x),
    (select string_agg(to_jsonb(x)::text, '|' order by x.subject_kind, x.subject_code, x.skill_code) from public.skill_requirements x
      where not (x.subject_kind = 'hull' and x.subject_code = any ((select codes from n)::text[]))),
    (select string_agg(to_jsonb(x)::text, '|' order by x.code) from public.ship_lines x),
    (select string_agg(to_jsonb(x)::text, '|' order by x.live_class, x.line_code) from public.npc_line_hulls x),
    (select string_agg(to_jsonb(x)::text, '|' order by x.class_code, x.pattern, x.item_code) from public.npc_loadouts x),
    (select string_agg(to_jsonb(x)::text, '|' order by x.class_code, x.stat) from public.ship_variety x)))),
  'functions', (select md5(string_agg(p.oid::regprocedure::text || ':' || md5(replace(pg_get_functiondef(p.oid), E'\r', '')) || ':' || coalesce(p.proacl::text, '') || ':' || p.provolatile::text || p.prosecdef::text || coalesce(p.proconfig::text, ''),
                        ',' order by p.oid::regprocedure::text))
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname in ('public', 'cmd', 'world', 'voyage') and p.prokind in ('f', 'p')),
  'scales', jsonb_build_object('hold', public.wc_int('hold_scale'), 'speed', public.wc_num('speed_scale')),
  'name_clash', (select count(*) from nm join public.ship_classes c on c.code <> nm.code
                  and (cmd.fold(c.name) = cmd.fold(nm.name) or cmd.fold(c.code) = cmd.fold(nm.name) or cmd.fold(c.name) = cmd.fold(nm.code))),
  'goods_missing', (select count(*) from unnest(array['abaca', 'canvas-duck', 'cedar', 'coco-fibre', 'coir', 'cordage', 'hemp', 'iron', 'live-oak', 'memel-fir', 'naval-timber', 'ships-nails', 'stockholm-tar', 'tar', 'teak', 'timber']) g(code) where not exists (select 1 from public.goods x where x.code = g.code)),
  'skills_missing', (select count(*) from unnest(array['CHN_CAPITAL', 'CHN_HEAVY', 'CHN_LIGHT', 'CHN_MEDIUM', 'CHN_SMALL', 'COMMAND', 'ENG_HEAVY', 'ENG_LIGHT', 'ENG_MEDIUM', 'ENG_SMALL', 'ESCORT_SUPPORT', 'ESP_HEAVY', 'ESP_LIGHT', 'ESP_MEDIUM', 'ESP_SMALL', 'FLEET_COMMAND', 'FRA_HEAVY', 'FRA_LIGHT', 'FRA_MEDIUM', 'FRA_SMALL', 'IND_CAPITAL', 'IND_HEAVY', 'IND_LIGHT', 'IND_MEDIUM', 'IND_SMALL', 'ITA_CAPITAL', 'ITA_HEAVY', 'ITA_LIGHT', 'ITA_MEDIUM', 'ITA_SMALL', 'JPN_CAPITAL', 'JPN_HEAVY', 'JPN_LIGHT', 'JPN_MEDIUM', 'JPN_SMALL', 'KOR_HEAVY', 'KOR_LIGHT', 'KOR_MEDIUM', 'KOR_SMALL', 'MERCHANT_SHIPS', 'NLD_HEAVY', 'NLD_LIGHT', 'NLD_MEDIUM', 'NLD_SMALL', 'OTT_CAPITAL', 'OTT_HEAVY', 'OTT_LIGHT', 'OTT_SMALL', 'PRT_CAPITAL', 'PRT_HEAVY', 'PRT_LIGHT', 'PRT_MEDIUM', 'PRT_SMALL', 'SHIPS_OF_WAR']) s(code) where not exists (select 1 from public.skills x where x.code = s.code)),
  'lines_with_no_tier3_yard', (select count(*) from public.ship_lines sl
                                where not exists (select 1 from public.port_buildings b where b.kind = 'building_yard' and b.tier >= 3 and public.port_countries(b.port_id) && sl.builder_nations)),
  'named_by_npc_or_knob', (select count(*) from n where exists (select 1 from public.npc_line_hulls x where x.class_code = any (n.codes))
                              or exists (select 1 from public.npc_loadouts x where x.class_code = any (n.codes))
                              or exists (select 1 from public.world_config k where jsonb_typeof(k.value) = 'string' and k.value #>> '{}' = any (n.codes))),
  'ships_of_new_classes', (select count(*) from public.ships s join public.ship_classes c on c.id = s.class_id, n where c.code = any (n.codes)),
  'news_row', (select count(*) from public.world_news w where w.key = 'update:0366')
)::text as j;
commit;
